import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1
    k = int(input_data[idx]); idx += 1

    s_str = input_data[idx]; idx += 1
    s = list(s_str)

    import math

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    tree_len = 4 * n
    tree = [[None for _ in range(10)] for _ in range(tree_len)]

    def build(node, start, end):
        if start == end:
            val = ord(s[start]) - ord('0')
            tree[node][val] = 1
            return
        mid = (start + end) // 2
        left_node = 2 * node
        right_node = 2 * node + 1
        build(left_node, start, mid)
        build(right_node, mid + 1, end)
        for v in range(10):
            tree[node][v] = tree[left_node][v] + tree[right_node][v]

    def update(node, start, end, l, r, val):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            tree[node] = [0] * 10
            tree[node][val] = end - start + 1
            return
        mid = (start + end) //2
        left_node = 2 * node
        right_node =2 * node + 1
        update(left_node, start, mid, l, r, val)
        update(right_node, mid + 1, end, l, r, val)
        for v in range(10):
            tree[node] = [0] * 10
            for vv in range(10):
                tree[node][vv] = tree[left_node][vv] + tree[right_node][vv]

    def query(node, start, end, l, r, val):
        if l > end or r < start:
            return 0
        if l <= start and end <= r:
            return tree[node][val]
        mid = (start + end) // 2
        left_count = query(2 * node, start, mid, l, r, val)
        right_count = query(2 * node + 1, mid + 1, end, l, r, val)

        return left_count + right_count

    build(1, 0, n - 1)

    results = []

    for _ in range(m + k):
        t = int(input_data[idx]); idx += 1
        l = int(input_data[idx]); idx += 1
        r = int(input_data[idx]); idx += 1

        if t == 1:
            c = int(input_data[idx]); idx += 1
            update(1, 0, n - 1, l - 1, r - 1, c)
        else:
            d = int(input_data[idx]); idx += 1

            length = r - l + 1
            if d >= length:
                results.append("YES")
                continue

            possible = True
            for i in range(d):
                offset = i
                count = 0
                step = d
                start_pos = l - 1 + offset
                end_pos = r - 1

                if start_pos > end_pos:
                    continue

                num_elements = (end_pos - start_pos) // step + 1

                current_val = None
                for j in range(num_elements):
                    pos = start_pos + j * step
                    if current_val is None:
                        cnt = query(1, 0, n - 1, pos, pos, 0)
                        for v in range(10):
                            if query(1, 0, n - 1, pos, pos + 1, v) > 0:
                                pass

                        temp_cnt = query(1, 0, n - 1, pos, min(pos + 1, end_pos), 0)
                        for v in range(10):
                            c_v = query(1, 0, n - 1, pos, end_pos, v)
                            if c_v > 0:
                                if current_val is None:
                                    current_val = v
                                elif v != current_val:
                                    possible = False
                                    break
                        if not possible:
                            break
                    else:
                        c_v = query(1, 0, n - 1, start_pos + j * step, min(start_pos + j * step, end_pos), current_val)
                        if c_v == 0:
                            possible = False
                            break
                if not possible:
                    break

            if possible:
                results.append("YES")
            else:
                results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    main()
